(function(){'use strict';const $=id=>document.getElementById(id),E=WormEconomy,W=PCWallet;let tab='heroes',slot=0,busy=false;
const layer=document.createElement('section');layer.id='metaLayer';layer.hidden=true;layer.innerHTML=`<div class="meta-shell"><header><div><small>WORM EXPEDITION</small><h2>우리 팀의 다음 모험.</h2></div><div class="meta-wallet"><b id="metaCoins">0 코인</b><span id="metaTokens">0 토큰</span></div><button id="metaClose" aria-label="상점과 미션 닫기">×</button></header><nav id="metaNav"><button data-meta="heroes">웜 상점·편성</button><button data-meta="weapons">무기 상점</button><button data-meta="missions">미션</button></nav><p id="metaMessage" role="status" aria-live="polite"></p><div id="metaBody"></div><footer>코인·토큰·편성은 현재 기기에 저장됩니다. 구매는 영구 해금이며 능력과 무기는 다음 새 전투부터 적용됩니다.</footer></div>`;document.body.append(layer);
const wallet=document.createElement('button');wallet.id='walletOpen';wallet.title='웜 코인 상점과 미션';wallet.textContent='◉ 0';document.querySelector('.top-actions').prepend(wallet);
const button=(text,action,disabled=false)=>{const b=document.createElement('button');b.textContent=text;b.disabled=disabled;b.onclick=action;return b;},el=(tag,text,cls)=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
async function action(fn,message=''){if(busy)return;busy=true;try{const r=await fn();$('metaMessage').textContent=message;render();return r;}catch(e){$('metaMessage').textContent=e.message;}finally{busy=false;}}
async function open(which='heroes'){tab=which;$('metaBody').scrollTop=0;window.dispatchEvent(new Event('pc:external-pause'));layer.hidden=false;await action(()=>W.run('sync'),'');render();}
function close(){layer.hidden=true;}wallet.onclick=()=>open();$('metaClose').onclick=close;document.querySelectorAll('[data-meta]').forEach(b=>b.onclick=()=>{tab=b.dataset.meta;render();$('metaBody').scrollTop=0;});document.addEventListener('keydown',e=>{if(!layer.hidden&&e.key==='Escape'){e.stopImmediatePropagation();close();}},true);
function render(){let state;try{state=W.read();}catch(e){$('metaMessage').textContent=e.message;return;}$('metaCoins').textContent=state.coins.toLocaleString()+' 웜 코인';$('metaTokens').textContent=state.tokens+' 훈장 토큰';wallet.textContent='◉ '+state.coins.toLocaleString();document.querySelectorAll('[data-meta]').forEach(b=>b.classList.toggle('selected',b.dataset.meta===tab));const body=$('metaBody');body.replaceChildren();
if(tab==='heroes'){const squad=el('div','','squad-grid');state.party.forEach((id,i)=>{const h=Critters.hero(id),b=button((i+1)+'번 · '+h.name,()=>{slot=i;render();});b.className=slot===i?'chosen':'';squad.append(b);});body.append(el('p','교체할 칸을 먼저 선택하세요. 다른 두 칸은 유지됩니다. 이미 편성된 특수 웜은 자리만 교환합니다.','meta-note'),squad);const grid=el('div','','meta-grid');for(const h of E.HEROES){const owned=state.heroes.includes(h.id),card=el('article','','meta-card'),canvas=document.createElement('canvas');canvas.width=160;canvas.height=110;Critters.drawHeroPortrait(canvas.getContext('2d'),h);card.append(canvas,el('h3',h.name),el('p',h.skill),el('small','체력 '+h.hp+' · 공격 '+Math.round(h.attack*100)+'%'));const can=state.coins>=h.price&&state.tokens>=(h.tokens||0);if(owned)card.append(button(state.party[slot]===h.id?'현재 '+(slot+1)+'번 편성':(slot+1)+'번 칸에 배치',()=>action(()=>W.run('equip',slot,h.id),'편성을 저장했습니다. 다음 새 전투에 적용됩니다.'),state.party[slot]===h.id));else card.append(button(h.price+' 코인'+(h.tokens?' + '+h.tokens+' 토큰':''),()=>action(()=>W.run('buy','hero',h.id),h.name+' 구매 완료! 교체할 칸에 직접 배치하세요.'),!can));grid.append(card);}body.append(grid);}
else if(tab==='weapons'){body.append(el('p','구매한 무기는 매 경기 정해진 탄약으로 지급됩니다. 턴·생존 조건을 충족해야 전투에서 사용할 수 있습니다.','meta-note'));const grid=el('div','','meta-grid');for(const w of E.SHOP_WEAPONS){const card=el('article','','meta-card'),owned=state.weapons.includes(w.id);card.append(el('div',w.id==='frost'?'❄':w.id==='leech'?'♥':w.id==='orbital'?'☄':'✦','shop-weapon-symbol'),el('h3',w.name),el('p',w.short),el('small','최대 피해 '+w.damage+' · 경기당 '+w.ammo+'회'));card.append(button(owned?'영구 보유 · 다음 전투 지급':w.price+' 코인'+(w.tokens?' + '+w.tokens+' 토큰':''),()=>action(()=>W.run('buy','weapon',w.id),w.name+' 영구 해금! 다음 새 전투부터 지급됩니다.'),owned||state.coins<w.price||state.tokens<(w.tokens||0)));grid.append(card);}body.append(grid);}
else {body.append(el('p','스테이지 AI전에서 승리하면 조건을 집계하고 보상을 자동 지급합니다. 일일 00:00 · 주간 월요일 00:00 · 월간 1일 00:00, 한국 시간 기준.','meta-note'));const active=W.missions();for(const [type,title]of [['daily','일일 미션'],['weekly','주간 미션'],['monthly','월간 미션']]){body.append(el('h3',title));const list=el('div','','mission-grid');for(const m of active[type]||[])list.append(missionCard(m));body.append(list);}body.append(el('h3','스테이지 도전 · 각 단계 영구 3개'));const choose=document.createElement('select');choose.ariaLabel='도전 스테이지 선택';for(let i=0;i<12;i++){const o=document.createElement('option');o.value=i;o.textContent=(i+1)+' 스테이지';choose.append(o);}const challengeList=el('div','','mission-grid');const fill=()=>challengeList.replaceChildren(...(state.challenges[+choose.value]||E.challenges(+choose.value)).map(missionCard));choose.onchange=fill;fill();body.append(choose,challengeList);body.append(el('h3','최근 코인 내역'));const logs=el('div','','coin-history');for(const l of state.log.slice(0,8))logs.append(el('p',(l.type==='buy'?'상품 구매':'스테이지 '+(l.stage+1)+' 승리')+' · '+(l.coins>0?'+':'')+l.coins+' 코인'+(l.tokens?' · +'+l.tokens+' 토큰':'')));body.append(logs);}}
function missionCard(m){const a=el('article','','mission-card');a.classList.toggle('complete',m.paid);a.append(el('b',m.title),el('span',Math.min(m.progress,m.target)+' / '+m.target),el('small','보상 '+m.coins+' 코인'+(m.tokens?' + '+m.tokens+' 토큰':'')),el('em',m.paid?'✓ 지급 완료':'진행 중 · 달성 시 자동 지급'));const p=document.createElement('progress');p.max=m.target;p.value=m.progress;a.append(p);return a;}
window.PCMeta={open,refresh:render};window.addEventListener('pc:wallet-changed',render);window.addEventListener('storage',e=>{if(e.key===E.KEY)render();});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!layer.hidden)action(()=>W.run('sync'));});setInterval(()=>{if(!layer.hidden)action(()=>W.run('sync'));},60000);W.run('sync').then(render).catch(e=>$('metaMessage').textContent=e.message);
})();
